//! 📦️ Paid stable reader and index ownership outlives every safely owned asynchronous graph borrow.
use super::*;
use super::super::graph::LayoutGraphRead;
use std::{mem::size_of,sync::Arc};
use semio_framework_value::retirement::arc_custody::arc_bytes;
/// 🛡️ A concrete reader owns original leases and paid descriptor storage until graph work and index close.
pub trait OwnedLayoutGraphRead:Send+Sync{fn graph(&self)->&dyn LayoutGraphRead;fn begin_close(&mut self);fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>;fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>;fn terminal_is_empty(&self)->bool;}
struct ReaderState{reader:Box<dyn OwnedLayoutGraphRead>,index:index::Index}
#[derive(Default)]pub struct OwnedLayoutGraphValidation{state:Option<Arc<ReaderState>>,reader_bytes:usize,reader_closing:bool,program:Option<Program>,program_bytes:usize,started:bool,done:bool,closing:bool,error:Option<&'static str>}
impl OwnedLayoutGraphValidation{
 const META:usize=256;
 fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Owned Layout graph validation frontier is invalid")}
 fn nested(d:RetirementDemand)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:d.copy_bytes.checked_add(Self::META).ok_or_else(Self::invalid)?,depth:d.depth.checked_add(1).ok_or_else(Self::invalid)?,..d})}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(Self::META),maximum_depth:g.maximum_depth.saturating_sub(1),..g}}
 fn paid(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes=p.copied_bytes.saturating_add(Self::META);p}
 fn error(error:ValueError)->ValueError{let p=Self::paid(error.retained_progress());error.with_retained_progress(p)}
 async fn check_owned(state:Arc<ReaderState>)->Validation{program::check_document(state.reader.graph(),state.index.slots()).await}
 fn future_bytes()->usize{fn bytes<F:Future>(_:fn(Arc<ReaderState>)->F)->usize{size_of::<F>()}bytes(Self::check_owned)}
 pub fn new()->Self{Default::default()}
 pub fn reader_birth_demand<G:OwnedLayoutGraphRead+'static>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<G>().saturating_mul(2).saturating_add(size_of::<ReaderState>().saturating_mul(2)).saturating_add(size_of::<Arc<ReaderState>>().saturating_mul(2)).saturating_add(Self::META),capacity_bytes:size_of::<G>().saturating_add(arc_bytes::<ReaderState>()),depth:1,..Default::default()}}
 pub fn start<G:OwnedLayoutGraphRead+'static>(&mut self,reader:G,g:RetainedCloneGrant)->Result<RetainedCloneProgress,(ValueError,G)>{let d=Self::reader_birth_demand::<G>();if self.state.is_some()||self.closing||!retained_clone_grant_admits(g,d){return Err((Self::invalid(),reader))}self.state=Some(Arc::new(ReaderState{reader:Box::new(reader),index:Default::default()}));self.reader_bytes=size_of::<G>();Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})}
 pub fn demand(&self,_body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(Self::invalid())}let state=self.state.as_ref().ok_or_else(Self::invalid)?;if self.done{return Ok(Default::default())}if !state.index.done(){return Self::nested(state.index.demand()?)}if !self.started{let bytes=Self::future_bytes();return Ok(RetirementDemand{copy_bytes:bytes.checked_mul(2).and_then(|n|n.checked_add(size_of::<Arc<ReaderState>>()*2+Self::META)).ok_or_else(Self::invalid)?,capacity_bytes:bytes,depth:1,..Default::default()})}Ok(RetirementDemand{copy_bytes:self.program_bytes.checked_mul(2).and_then(|n|n.checked_add(1024+Self::META)).ok_or_else(Self::invalid)?,depth:1,..Default::default()})}
 pub fn advance(&mut self,body:usize,g:RetainedCloneGrant)->Result<ValidationAdvance,ValueError>{let d=self.demand(body)?;let mut out=ValidationAdvance{progress:Default::default(),done:self.done,error:self.error};if self.done||!retained_clone_grant_admits(g,d){return Ok(out)}if !self.state.as_ref().ok_or_else(Self::invalid)?.index.done(){let state=Arc::get_mut(self.state.as_mut().ok_or_else(Self::invalid)?).ok_or_else(Self::invalid)?;out.progress=Self::paid(state.index.advance(state.reader.graph(),Self::child(g)).map_err(Self::error)?);if let Some(error)=state.index.error(){self.error=Some(error);self.done=true;out.done=true;out.error=Some(error)}return Ok(out)}out.progress=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if !self.started{self.program_bytes=Self::future_bytes();self.program=Some(Box::pin(Self::check_owned(Arc::clone(self.state.as_ref().ok_or_else(Self::invalid)?))));self.started=true;out.progress.retained_capacity_bytes=self.program_bytes;return Ok(out)}let mut cx=Context::from_waker(Waker::noop());if let Poll::Ready(result)=self.program.as_mut().ok_or_else(Self::invalid)?.as_mut().poll(&mut cx){self.done=true;self.error=result.err();out.done=true;out.error=self.error}Ok(out)}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.program.is_some(){return Ok(RetirementDemand{copy_bytes:self.program_bytes.checked_mul(2).and_then(|n|n.checked_add(Self::META)).ok_or_else(Self::invalid)?,release_bytes:self.program_bytes,depth:1,..Default::default()})}if let Some(state)=&self.state{if Arc::strong_count(state)!=1||Arc::weak_count(state)!=0{return Err(Self::invalid())}if !state.index.terminal_is_empty(){return Self::nested(state.index.close_demand())}if !self.reader_closing{return Ok(RetirementDemand{copy_bytes:Self::META,depth:1,..Default::default()})}if !state.reader.terminal_is_empty(){return Self::nested(state.reader.close_demand(body.saturating_sub(Self::META))?)}return Ok(RetirementDemand{copy_bytes:self.reader_bytes.checked_mul(2).and_then(|n|n.checked_add(size_of::<ReaderState>()*2+Self::META)).ok_or_else(Self::invalid)?,release_bytes:self.reader_bytes.checked_add(arc_bytes::<ReaderState>()).ok_or_else(Self::invalid)?,depth:1,..Default::default()})}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(Self::invalid())}let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.program.is_some(){self.program=None;self.program_bytes=0;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))}let state=Arc::get_mut(self.state.as_mut().ok_or_else(Self::invalid)?).ok_or_else(Self::invalid)?;if !state.index.terminal_is_empty(){return state.index.close_step(Self::child(g)).map(|p|RetainedCloneStep::Progress(Self::paid(p))).map_err(Self::error)}if !self.reader_closing{state.reader.begin_close();self.reader_closing=true;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if !state.reader.terminal_is_empty(){return state.reader.close_step(Self::child(g)).map(|p|RetainedCloneStep::Progress(Self::paid(p.progress()))).map_err(Self::error)}self.state=None;self.reader_bytes=0;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))}
 pub fn terminal_is_empty(&self)->bool{self.state.is_none()&&self.program.is_none()&&self.program_bytes==0}
}
impl Drop for OwnedLayoutGraphValidation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Owned graph reader and continuation require original-funded close")}}
